import { AudioPlayer } from '@refy-design/web';
import type { ComponentProps } from 'react';
const media = {
  tones: 'https://refy.design/demo/tons.mp3',
};
const photos = {
  coverPlaylist: 'https://refy.design/demo/capa-playlist.webp',
};
export function Example() {
  const args: Pick<
    ComponentProps<typeof AudioPlayer>,
    'src' | 'title' | 'description' | 'artwork' | 'duration'
  > = {
    src: media.tones,
    title: 'Four tones',
    description: 'Sound check · 10 s',
    artwork: photos.coverPlaylist,
    duration: 10,
  };
  return <AudioPlayer {...args} />;
}

